import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)
    email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
    def process_item(item):
        if isinstance(item, dict):
            return {k: process_item(v) for k, v in item.items() if v is not None}
        elif isinstance(item, list):
            return [process_item(i) for i in item if i is not None]
        elif isinstance(item, str):
            return re.sub(email_pattern, REPLACE_NONE, item)
        else:
            return item
    processed = process_item(data)
    all_values = []
    def collect_values(item):
        if isinstance(item, dict):
            for v in item.values():
                collect_values(v)
        elif isinstance(item, list):
            for v in item:
                collect_values(v)
        else:
            all_values.append(item)
    collect_values(processed)
    value_counts = Counter(all_values)
    return {"data": processed, "value_counts": value_counts}
